import React, { useEffect, useRef, useState } from 'react';
import { Alert, Button, Empty, Form, Input, Modal, Popconfirm, Select, Space, Table, Tooltip, Typography } from 'antd';
import { DeleteOutlined, PlusOutlined, ReloadOutlined, QuestionCircleOutlined } from '@ant-design/icons';

const base = '/api/console/applications/{application_id}/api-keys';
const formatDate = value => value ? new Date(value).toLocaleString('zh-CN', { timeZone: 'Asia/Shanghai', hour12: false }) : '未使用';

export default function ApplicationApiKeyTable({ ctx }) {
  const [catalog, setCatalog] = useState(null);
  const [loading, setLoading] = useState(true);
  const [busy, setBusy] = useState(false);
  const [notice, setNotice] = useState(null);
  const [creating, setCreating] = useState(false);
  const [created, setCreated] = useState(null);
  const [form] = Form.useForm();
  const [sort, setSort] = useState({ sort_by: 'created_at', sort_order: 'desc' });
  const sortRef = useRef({ sort_by: 'created_at', sort_order: 'desc' });
  const [pagination, setPagination] = useState({ current: 1, pageSize: 10 });
  const revision = useRef(0);
  const action = useRef(false);

  async function refresh() {
    const request = ++revision.current;
    setLoading(true);
    try {
      const response = await ctx.api.get('/api/ex/application-api-key-table', { query: sortRef.current });
      if (request === revision.current) setCatalog(response.catalog);
    } catch (e) {
      if (request === revision.current) setNotice({ type: 'error', message: '读取 API Keys 失败：' + e.message });
    } finally { if (request === revision.current) setLoading(false); }
  }
  useEffect(() => { refresh(); return () => { revision.current++; }; }, []);

  function changeTable(nextPage, filters, sorter, extra) {
    if (extra.action === 'sort') {
      const next = { sort_by: sorter.field, sort_order: sorter.order === 'ascend' ? 'asc' : 'desc' };
      sortRef.current = next;
      setSort(next);
      setPagination({ current: 1, pageSize: nextPage.pageSize });
      refresh();
    } else {
      setPagination({ current: nextPage.current, pageSize: nextPage.pageSize });
    }
  }

  async function createKey() {
    if (action.current) return;
    let values;
    try { values = await form.validateFields(); } catch { return; }
    action.current = true; setBusy(true); setNotice(null);
    try {
      const key = await ctx.api.post(base, { path: { application_id: values.application_id }, body: { name: values.name.trim() } });
      setCreating(false);
      setCreated(key);
      form.resetFields();
      await refresh();
    } catch (e) { setNotice({ type: 'error', message: '创建 Key 失败：' + e.message }); }
    finally { action.current = false; setBusy(false); }
  }

  async function deleteKey(record) {
    if (action.current) return;
    action.current = true; setBusy(true); setNotice(null);
    try {
      await ctx.api.delete(base + '/{key_id}', { path: { application_id: record.application_id, key_id: record.id } });
      setNotice({ type: 'success', message: 'Key 已删除。' });
      await refresh();
    } catch (e) { setNotice({ type: 'error', message: '删除 Key 失败：' + e.message }); }
    finally { action.current = false; setBusy(false); }
  }

  return <div style={{ padding: 24, minWidth: 0 }}>
    <div style={{ display: 'flex', flexWrap: 'wrap', alignItems: 'center', justifyContent: 'space-between', gap: 16, marginBottom: 24 }}>
      <div>
        <Typography.Title level={4} style={{ margin: '0 0 8px' }}>API Keys</Typography.Title>
        <Typography.Text type="secondary">{catalog ? '已创建 ' + catalog.items.length + ' 个 Key，按所属应用标记分组。' : '按所属应用统一管理 API Keys。'}</Typography.Text>
      </div>
      <Space>
        <Button aria-label="刷新 API Keys" icon={<ReloadOutlined aria-hidden />} onClick={refresh} loading={loading} disabled={busy}>刷新</Button>
        <Button type="primary" icon={<PlusOutlined aria-hidden />} disabled={busy || loading || !catalog?.applications.length}
          onClick={() => { form.resetFields(); setNotice(null); setCreating(true); }}>创建 Key</Button>
      </Space>
    </div>
    {notice && <Alert {...notice} showIcon closable onClose={() => setNotice(null)} style={{ marginBottom: 16 }} />}
    <Table aria-label="应用 API Keys" rowKey="id" dataSource={catalog?.items || []} loading={loading} scroll={{ x: 1120 }}
      onChange={changeTable} sortDirections={['ascend', 'descend', 'ascend']}
      pagination={{ ...pagination, showSizeChanger: true, pageSizeOptions: [10, 20, 50] }}
      locale={{ emptyText: <Empty description="暂无 API Key" /> }} columns={[
        { title: '名称', dataIndex: 'name', width: 160, ellipsis: true },
        { title: '应用分组', dataIndex: 'application_name', width: 240, render: (name, record) => <Tooltip title={record.application_id}><Typography.Text style={{ display: 'inline-block', maxWidth: '100%', whiteSpace: 'normal', overflowWrap: 'anywhere' }}>{name}</Typography.Text></Tooltip> },
        { title: <Space size={6}>密钥<Tooltip title="只显示密钥前缀，完整密钥仅在创建时显示一次。"><QuestionCircleOutlined aria-label="密钥展示说明" /></Tooltip></Space>, dataIndex: 'token_prefix', width: 190, render: prefix => <Typography.Text code>{prefix}****</Typography.Text> },
        { title: '创建时间', dataIndex: 'created_at', width: 190, render: formatDate, sorter: true, sortOrder: sort.sort_by === 'created_at' ? (sort.sort_order === 'asc' ? 'ascend' : 'descend') : null },
        { title: '最后使用时间', dataIndex: 'last_used_at', width: 190, render: formatDate, sorter: true, sortOrder: sort.sort_by === 'last_used_at' ? (sort.sort_order === 'asc' ? 'ascend' : 'descend') : null },
        { title: '操作', key: 'actions', width: 90, render: (_, record) => <Popconfirm title={'删除 Key“' + record.name + '”？'} description={'所属应用：' + record.application_name + '。删除后该密钥立即失效。'} onConfirm={() => deleteKey(record)} okText="删除" cancelText="取消" disabled={busy || loading}>
          <Button type="text" danger aria-label={'删除 Key ' + record.name} icon={<DeleteOutlined aria-hidden />} disabled={busy || loading} />
        </Popconfirm> },
      ]} />
    {creating && <Modal title="创建 API Key" open onOk={createKey} onCancel={() => setCreating(false)} okText="创建" cancelText="取消" confirmLoading={busy} closable={!busy} maskClosable={false} cancelButtonProps={{ disabled: busy }}>
      {notice?.type === 'error' && <Alert {...notice} showIcon style={{ marginBottom: 16 }} />}
      <Form form={form} layout="vertical" disabled={busy}>
        <Form.Item label="应用分组" name="application_id" rules={[{ required: true, message: '请选择所属应用' }]}>
          <Select aria-label="所属应用" showSearch optionFilterProp="label" placeholder="选择所属应用" options={catalog.applications.map(app => ({ value: app.id, label: app.name }))} />
        </Form.Item>
        <Form.Item label="名称" name="name" rules={[{ required: true, whitespace: true, message: '请输入 Key 名称' }]}><Input maxLength={100} placeholder="例如：开发环境" /></Form.Item>
      </Form>
    </Modal>}
    {created && <Modal title="保存 API Key" open onCancel={() => setCreated(null)} maskClosable={false} footer={<Button type="primary" onClick={() => setCreated(null)}>完成</Button>}>
      <Alert type="info" showIcon message="完整密钥仅显示这一次，请复制并妥善保存。关闭后只能查看密钥前缀。" style={{ marginBottom: 20 }} />
      <Typography.Paragraph copyable={{ text: created.token }} code style={{ overflowWrap: 'anywhere' }}>{created.token}</Typography.Paragraph>
    </Modal>}
  </div>;
}
